        ["Damage tanked"] = ["Dano recebido", "Dégâts encaissés", "Getankter Schaden", "Sát thương gánh chịu", "받은 피해"],
        ["Gold"] = ["Ouro", "Or", "Gold", "Vàng", "골드"],
        ["Crowd control (s)"] = ["Controle de grupo (s)", "Contrôle (s)", "Massenkontrolle (s)", "Khống chế (giây)", "군중 제어 (초)"],
        ["You were the best of all 10 players this game. Well played!"] = ["Você foi o melhor dos 10 jogadores nesta partida. Bem jogado!", "Vous avez été le meilleur des 10 joueurs de cette partie. Bien joué !", "Du warst der Beste aller 10 Spieler in diesem Spiel. Gut gespielt!", "Bạn là người chơi tốt nhất trong 10 người trận này. Chơi hay lắm!", "이번 게임 10명 중 최고 플레이어였습니다. 잘하셨어요!"],
        ["You respawned {0} times with 1,300+ unspent gold (avg {1}). When dead you're in the shop: buy before you respawn."] = ["Você renasceu {0} vezes com 1.300+ de ouro sem gastar (média {1:N0}). Morto você está na loja: compre antes de renascer.", "Vous êtes réapparu {0} fois avec 1 300+ or non dépensé (moyenne {1:N0}). Mort, vous êtes dans la boutique : achetez avant de réapparaître.", "Du bist {0}-mal mit 1.300+ ungenutztem Gold wiederbelebt worden (Schnitt {1:N0}). Tot bist du im Shop: kauf vor dem Respawn.", "Bạn hồi sinh {0} lần mà còn 1.300+ vàng chưa tiêu (trung bình {1:N0}). Khi chết bạn đang ở cửa hàng: hãy mua trước khi hồi sinh.", "1,300+ 골드를 쓰지 않고 {0}회 부활 (평균 {1:N0}). 사망 시 상점에 있으니 부활 전에 아이템을 구매하세요."],
        ["Min {0}: you took “{1}” ({2}) over “{3}” ({4}). Unless you had a plan, the other one performs better on your champion."] = ["Min {0:0}: você pegou “{1}” ({2}) em vez de “{3}” ({4}). A não ser que tivesse um plano, o outro rende mais com seu campeão.", "Min {0:0} : vous avez pris « {1} » ({2}) plutôt que « {3} » ({4}). Sauf si vous aviez un plan, l'autre rend mieux avec votre champion.", "Min. {0:0}: Du hast „{1}“ ({2}) statt „{3}“ ({4}) genommen. Außer du hattest einen Plan, bringt die andere mit deinem Champion mehr.", "Phút {0:0}: bạn chọn “{1}” ({2}) thay vì “{3}” ({4}). Trừ khi bạn có kế hoạch, lựa chọn kia hiệu quả hơn với tướng của bạn.", "{0:0}분: \"{1}\" ({2}) 대신 \"{3}\" ({4}) 선택. 계획이 없었다면 다른 쪽이 내 챔피언에게 더 좋습니다."],
        ["You tanked the most damage in the game: your team could hit from behind you."] = ["Você aguentou mais dano que todos na partida: seu time pôde atacar protegido por você.", "Vous avez encaissé le plus de dégâts de la partie : votre équipe a pu frapper derrière vous.", "Du hast im Spiel den meisten Schaden getankt: dein Team konnte hinter dir zuschlagen.", "Bạn gánh nhiều sát thương nhất trận: đồng đội có thể đánh từ phía sau bạn.", "게임에서 가장 많은 피해를 탱킹했습니다: 팀원들이 뒤에서 안전하게 공격할 수 있었어요."],
        ["Low damage (#{0} of 10) and not much tanking either: check the “Adapt” tab of the panel during the game."] = ["Pouco dano (#{0} de 10) e também pouco tanque: olhe a aba “Adaptar” do painel durante a partida.", "Peu de dégâts (#{0} sur 10) et peu d'encaissement : regardez l'onglet « Adapter » du panneau pendant la partie.", "Wenig Schaden (#{0} von 10) und auch wenig getankt: schau während des Spiels in den Tab „Anpassen“ des Panels.", "Ít sát thương (hạng {0}/10) và cũng ít đỡ đòn: hãy xem thẻ “Thích ứng” của bảng trong trận.", "피해 낮음 (10명 중 {0}위) 탱킹도 적음: 게임 중 패널의 \"적응\" 탭을 확인하세요."],
        ["You died {0} times: each death feeds the enemy a lot of gold; pick fights with your team nearby."] = ["Você morreu {0} vezes: cada morte dá muito ouro ao inimigo; lute com seu time por perto.", "Vous êtes mort {0} fois : chaque mort donne beaucoup d'or à l'ennemi ; engagez avec votre équipe à proximité.", "Du bist {0}-mal gestorben: jeder Tod gibt dem Gegner viel Gold; kämpfe mit deinem Team in der Nähe.", "Bạn chết {0} lần: mỗi lần chết cho địch nhiều vàng; hãy giao tranh khi đồng đội ở gần.", "{0}회 사망: 사망마다 적에게 골드를 많이 줍니다. 팀원 근처에서 싸우세요."],
        ["With {0} you took {1}; in Mayhem {2} wins more on it: {3} vs {4}."] = ["Com {0} você pegou {1}; na Desordem {2} ganha mais com ele: {3:P1} contra {4:P1}.", "Avec {0} vous avez pris {1} ; en ARAM du chaos, {2} gagne plus avec lui : {3:P1} contre {4:P1}.", "Mit {0} hast du {1} genommen; in ARAM: Chaos gewinnt {2} mit ihm mehr: {3:P1} gegen {4:P1}.", "Với {0} bạn chọn {1}; ở Hỗn Loạn {2} thắng nhiều hơn với tướng này: {3:P1} so với {4:P1}.", "{0}으로 {1} 선택; 무작위 총력전에서 {2}는 더 많이 승리: {3:P1} vs {4:P1}."],
        ["With {0} you took {1}, which almost nobody takes on it in Mayhem; {2} wins {3}."] = ["Com {0} você pegou {1}, que quase ninguém pega com ele na Desordem; {2} ganha {3:P1}.", "Avec {0} vous avez pris {1}, que presque personne ne prend avec lui en ARAM du chaos ; {2} gagne {3:P1}.", "Mit {0} hast du {1} genommen, das in ARAM: Chaos fast niemand mit ihm nimmt; {2} gewinnt {3:P1}.", "Với {0} bạn chọn {1}, hầu như không ai chọn với tướng này ở Hỗn Loạn; {2} thắng {3:P1}.", "{0}으로 {1} 선택, 무작위 총력전에서 거의 아무도 선택하지 않음; {2} 승률 {3:P1}."],
        ["The enemy healed a lot ({0}) and you had no grievous wounds: {1}, {2} or {3}, depending on your build (the panel's “Adapt” tab tells you which)."] = ["O inimigo se curou muito ({0}) e você não tinha feridas dolorosas: {1}, {2} ou {3}, conforme sua build (a aba “Adaptar” do painel diz qual).", "L'ennemi s'est beaucoup soigné ({0}) et vous n'aviez pas de blessures graves : {1}, {2} ou {3}, selon votre build (l'onglet « Adapter » du panneau vous dit lequel).", "Der Gegner hat sich stark geheilt ({0}) und du hattest keine Klaffenden Wunden: {1}, {2} oder {3}, je nach Build (der Tab „Anpassen“ des Panels sagt dir, welches).", "Địch hồi máu nhiều ({0}) mà bạn không có vết thương sâu: {1}, {2} hoặc {3}, tùy build (thẻ “Thích ứng” của bảng sẽ cho biết món nào).", "적이 많이 회복 ({0}) 했지만 상처 없음: {1}, {2} 또는 {3} (빌드에 따라 패널의 \"적응\" 탭 참고)."],
        ["{0} of the enemy damage was magic and you died {1} times with no magic resist: {2} or an item with magic resist would have helped."] = ["{0:P0} do dano inimigo foi mágico e você morreu {1} vezes sem resistência mágica: {2} ou um item com resistência mágica teria ajudado.", "{0:P0} des dégâts ennemis étaient magiques et vous êtes mort {1} fois sans résistance magique : {2} ou un objet avec de la résistance magique aurait aidé.", "{0:P0} des gegnerischen Schadens war magisch und du bist {1}-mal ohne Magieresistenz gestorben: {2} oder ein Item mit Magieresistenz hätte geholfen.", "{0:P0} sát thương địch là phép và bạn chết {1} lần mà không có kháng phép: {2} hoặc một món có kháng phép sẽ giúp ích.", "적 피해의 {0:P0}이 마법이고 마법 저항력 없이 {1}회 사망: {2} 또는 마법 저항력 아이템이 도움이 됐을 것입니다."],
        ["{0} of the enemy damage was physical and you died {1} times with no armor: {2} or an item with armor would have helped."] = ["{0:P0} do dano inimigo foi físico e você morreu {1} vezes sem armadura: {2} ou um item com armadura teria ajudado.", "{0:P0} des dégâts ennemis étaient physiques et vous êtes mort {1} fois sans armure : {2} ou un objet avec de l'armure aurait aidé.", "{0:P0} des gegnerischen Schadens war physisch und du bist {1}-mal ohne Rüstung gestorben: {2} oder ein Item mit Rüstung hätte geholfen.", "{0:P0} sát thương địch là vật lý và bạn chết {1} lần mà không có giáp: {2} hoặc một món có giáp sẽ giúp ích.", "적 피해의 {0:P0}이 물리이고 방어력 없이 {1}회 사망: {2} 또는 방어력 아이템이 도움이 됐을 것입니다."],
        ["You took part in {0} of your team's kills: ARAM is won by fighting together, without hanging back or diving alone."] = ["Você participou de {0:P0} dos abates do seu time: o ARAM se ganha lutando juntos, sem ficar para trás nem entrar sozinho.", "Vous avez participé à {0:P0} des kills de votre équipe : l'ARAM se gagne en combattant ensemble, sans rester en retrait ni plonger seul.", "Du warst an {0:P0} der Kills deines Teams beteiligt: ARAM gewinnt man gemeinsam, ohne zurückzubleiben oder allein reinzugehen.", "Bạn tham gia {0:P0} số mạng hạ gục của đội: ARAM thắng nhờ đánh cùng nhau, đừng đứng ngoài hay lao vào một mình.", "팀 킬의 {0:P0}에 관여: 무작위 총력전은 함께 싸워야 이깁니다. 혼자 뒤처지거나 혼자 돌진하지 마세요."],
        ["You win {0} with {1} ({2} games): grab it if it shows up on the bench."] = ["Você ganha {0:P0} com {1} ({2} partidas): pegue-o se aparecer no banco.", "Vous gagnez {0:P0} avec {1} ({2} parties) : prenez-le s'il apparaît sur le banc.", "Du gewinnst {0:P0} mit {1} ({2} Spiele): nimm ihn, wenn er auf der Bank auftaucht.", "Bạn thắng {0:P0} với {1} ({2} trận): hãy lấy nếu tướng này xuất hiện ở hàng chờ.", "{1}로 승률 {0:P0} ({2}게임): 교환석에 나오면 선택하세요."],
        ["You only win {0} with {1} ({2} games): check its page in “Champions” to see which build wins more."] = ["Você só ganha {0:P0} com {1} ({2} partidas): veja a página dele em “Campeões” para saber qual build ganha mais.", "Vous ne gagnez que {0:P0} avec {1} ({2} parties) : regardez sa page dans « Champions » pour voir quelle build gagne le plus.", "Du gewinnst mit {1} nur {0:P0} ({2} Spiele): schau dir seine Seite unter „Champions“ an, um zu sehen, welcher Build mehr gewinnt.", "Bạn chỉ thắng {0:P0} với {1} ({2} trận): xem trang của tướng này trong “Tướng” để biết build nào thắng nhiều hơn.", "{1}로 승률 겨우 {0:P0} ({2}게임): \"챔피언\" 페이지에서 어떤 빌드가 더 승리하는지 확인하세요."],
        ["You die {0} times per game and the other players in your games {1}: an earlier defensive item (the panel's “Adapt” tab tells you which) or fighting closer to your team can change that."] = ["Você morre {0:0.#} vezes por partida e os outros jogadores das suas partidas {1:0.#}: um item defensivo mais cedo (a aba “Adaptar” do painel diz qual) ou lutar mais perto do seu time pode mudar isso.", "Vous mourez {0:0.#} fois par partie et les autres joueurs de vos parties {1:0.#} : un objet défensif plus tôt (l'onglet « Adapter » du panneau vous dit lequel) ou combattre plus près de votre équipe peut changer ça.", "Du stirbst {0:0.#}-mal pro Spiel, die anderen Spieler in deinen Spielen {1:0.#}-mal: ein früheres Verteidigungs-Item (der Tab „Anpassen“ des Panels sagt dir, welches) oder näher am Team kämpfen kann das ändern.", "Bạn chết {0:0.#} lần mỗi trận, còn những người chơi khác trong các trận của bạn {1:0.#}: một món phòng thủ sớm hơn (thẻ “Thích ứng” của bảng sẽ cho biết) hoặc đánh gần đồng đội hơn có thể thay đổi điều đó.", "게임당 {0:0.#}회 사망, 같은 게임 플레이어 평균 {1:0.#}회: 방어 아이템을 더 일찍 구매하거나 (패널 \"적응\" 탭 참고) 팀원 가까이 싸우면 달라질 수 있습니다."],
        ["You take part in {0} of your team's kills; the other players in your games in {1}. ARAM fights are won together: don't hang back or dive alone."] = ["Você participa de {0:P0} dos abates do seu time; os outros jogadores das suas partidas, de {1:P0}. As lutas do ARAM se ganham juntos: não fique para trás nem entre sozinho.", "Vous participez à {0:P0} des kills de votre équipe ; les autres joueurs de vos parties à {1:P0}. Les combats d'ARAM se gagnent ensemble : ne restez pas en retrait et ne plongez pas seul.", "Du bist an {0:P0} der Kills deines Teams beteiligt; die anderen Spieler in deinen Spielen an {1:P0}. ARAM-Kämpfe gewinnt man gemeinsam: bleib nicht zurück und geh nicht allein rein.", "Bạn tham gia {0:P0} số mạng hạ gục của đội; những người chơi khác trong các trận của bạn {1:P0}. Giao tranh ARAM thắng nhờ đánh cùng nhau: đừng đứng ngoài hay lao vào một mình.", "팀 킬의 {0:P0}에 관여; 같은 게임 플레이어 평균 {1:P0}. 무작위 총력전은 함께 이깁니다. 뒤처지거나 혼자 돌진하지 마세요."],
        ["On damage champions you usually place #{0} of 10 in damage: check whether your augments fit your build (on the card, “⚡ …”) and follow the panel's “Buy now”."] = ["Com campeões de dano você costuma ficar em #{0:0} de 10 em dano: veja se seus aprimoramentos combinam com sua build (na carta, “⚡ …”) e siga o “Compre agora” do painel.", "Avec des champions de dégâts, vous finissez souvent #{0:0} sur 10 en dégâts : vérifiez que vos optimisations vont avec votre build (sur la carte, « ⚡ … ») et suivez le « Achetez maintenant » du panneau.", "Mit Schadens-Champions landest du meist auf #{0:0} von 10 beim Schaden: prüfe, ob deine Augmentierungen zu deinem Build passen (auf der Karte „⚡ …“), und folge „Jetzt kaufen“ im Panel.", "Với tướng gây sát thương bạn thường đứng hạng {0:0}/10 về sát thương: kiểm tra Nâng Cấp có hợp build không (trên thẻ, “⚡ …”) và làm theo “Mua ngay” của bảng.", "딜러 챔피언으로 보통 피해 {0:0}위 (10명 중): 증강이 빌드에 맞는지 확인하고 (카드에서 \"⚡ …\") 패널의 \"지금 구매\"를 따르세요."],
        ["On damage champions you're usually among the top damage dealers: #{0} of 10 on average. Well played!"] = ["Com campeões de dano você costuma estar entre os que mais causam dano: #{0:0.#} de 10 em média. Bem jogado!", "Avec des champions de dégâts, vous êtes souvent parmi ceux qui font le plus de dégâts : #{0:0.#} sur 10 en moyenne. Bien joué !", "Mit Schadens-Champions gehörst du meist zu den stärksten Schadensverursachern: im Schnitt #{0:0.#} von 10. Gut gespielt!", "Với tướng gây sát thương bạn thường nằm trong nhóm gây sát thương cao nhất: trung bình hạng {0:0.#}/10. Chơi hay lắm!", "딜러 챔피언으로 보통 피해 상위권: 평균 10명 중 {0:0.#}위. 잘하셨어요!"],
        ["In {0} of your recent games the enemy healed a lot ({1}…) and you had no grievous wounds: {2}, {3} or {4}, depending on your build."] = ["Em {0} das suas últimas partidas o inimigo se curou muito ({1}…) e você não tinha feridas dolorosas: {2}, {3} ou {4}, conforme sua build.", "Dans {0} de vos dernières parties, l'ennemi s'est beaucoup soigné ({1}…) et vous n'aviez pas de blessures graves : {2}, {3} ou {4}, selon votre build.", "In {0} deiner letzten Spiele hat sich der Gegner stark geheilt ({1}…) und du hattest keine Klaffenden Wunden: {2}, {3} oder {4}, je nach Build.", "Trong {0} trận gần đây địch hồi máu nhiều ({1}…) mà bạn không có vết thương sâu: {2}, {3} hoặc {4}, tùy build.", "최근 {0}게임에서 적이 많이 회복 ({1}…) 했지만 상처 없음: {2}, {3} 또는 {4} (빌드에 따라)."],
        ["In {0} games against heavy magic damage you died 7+ times with no magic resist at all: {1} or one item with magic resist is usually enough."] = ["Em {0} partidas contra muito dano mágico você morreu 7+ vezes sem nenhuma resistência mágica: {1} ou um item com resistência mágica costuma bastar.", "Dans {0} parties contre beaucoup de dégâts magiques, vous êtes mort 7+ fois sans aucune résistance magique : {1} ou un objet avec de la résistance magique suffit souvent.", "In {0} Spielen gegen viel magischen Schaden bist du 7+-mal ohne jede Magieresistenz gestorben: {1} oder ein Item mit Magieresistenz reicht meist.", "Trong {0} trận gặp nhiều sát thương phép bạn chết 7+ lần mà không có chút kháng phép nào: {1} hoặc một món có kháng phép thường là đủ.", "{0}게임에서 마법 피해 많은 적 상대로 마법 저항력 없이 7+회 사망: {1} 또는 마법 저항력 아이템 하나면 충분합니다."],
        ["In {0} games against heavy physical damage you died 7+ times with no armor at all: {1} or one item with armor is usually enough."] = ["Em {0} partidas contra muito dano físico você morreu 7+ vezes sem nenhuma armadura: {1} ou um item com armadura costuma bastar.", "Dans {0} parties contre beaucoup de dégâts physiques, vous êtes mort 7+ fois sans aucune armure : {1} ou un objet avec de l'armure suffit souvent.", "In {0} Spielen gegen viel physischen Schaden bist du 7+-mal ohne jede Rüstung gestorben: {1} oder ein Item mit Rüstung reicht meist.", "Trong {0} trận gặp nhiều sát thương vật lý bạn chết 7+ lần mà không có chút giáp nào: {1} hoặc một món có giáp thường là đủ.", "{0}게임에서 물리 피해 많은 적 상대로 방어력 없이 7+회 사망: {1} 또는 방어력 아이템 하나면 충분합니다."],
        ["{0} pentakill{1} in your recent games!"] = ["{0} pentakill{1} nas suas últimas partidas!", "{0} pentakill{1} dans vos dernières parties !", "{0} Pentakill{1} in deinen letzten Spielen!", "{0} pentakill trong các trận gần đây!", "최근 게임에서 펜타킬 {0}회!"],
        ["In your recent games you went back to fight {0} times with 1,300+ unspent gold: when dead you're in the shop, buy before respawning (the panel opens on “Buy” by itself)."] = ["Nas suas últimas partidas você voltou a lutar {0} vezes com 1.300+ de ouro sem gastar: morto você está na loja, compre antes de renascer (o painel abre sozinho em “Compras”).", "Dans vos dernières parties, vous êtes retourné combattre {0} fois avec 1 300+ or non dépensé : mort, vous êtes dans la boutique, achetez avant de réapparaître (le panneau s'ouvre tout seul sur « Achats »).", "In deinen letzten Spielen bist du {0}-mal mit 1.300+ ungenutztem Gold zurück in den Kampf: tot bist du im Shop, kauf vor dem Respawn (das Panel öffnet sich von selbst auf „Kaufen“).", "Trong các trận gần đây bạn quay lại giao tranh {0} lần mà còn 1.300+ vàng chưa tiêu: khi chết bạn đang ở cửa hàng, hãy mua trước khi hồi sinh (bảng tự mở thẻ “Mua đồ”).", "최근 게임에서 1,300+ 골드를 쓰지 않고 {0}번 전투로 복귀: 사망 시 상점에 있으니 부활 전에 구매하세요 (패널이 자동으로 \"구매\" 탭 열림)."],
        ["In {0} of your last {1} augment picks you took a card 15+ points below the best one. Unless you were going for something (a combo, your build), the top-scored card usually performs better on your champion."] = ["Em {0} das suas últimas {1} escolhas de aprimoramento você pegou uma carta 15+ pontos abaixo da melhor. A não ser que buscasse algo (um combo, sua build), a carta com melhor nota costuma render mais com seu campeão.", "Dans {0} de vos {1} derniers choix d'optimisation, vous avez pris une carte 15+ points sous la meilleure. Sauf si vous visiez quelque chose (un combo, votre build), la carte la mieux notée rend souvent mieux avec votre champion.", "Bei {0} deiner letzten {1} Augmentierungs-Wahlen hast du eine Karte 15+ Punkte unter der besten genommen. Außer du wolltest etwas Bestimmtes (eine Kombi, deinen Build), bringt die bestbewertete Karte mit deinem Champion meist mehr.", "Trong {0}/{1} lần chọn Nâng Cấp gần đây bạn lấy thẻ thấp hơn thẻ tốt nhất 15+ điểm. Trừ khi bạn nhắm đến điều gì (một combo, build của bạn), thẻ điểm cao nhất thường hiệu quả hơn với tướng của bạn.", "최근 {1}번의 증강 선택 중 {0}번을 최고점보다 15점 이상 낮은 카드 선택. 콤보나 빌드 전략이 없다면 최고점 카드가 보통 더 좋습니다."],
        ["In your last {0} picks you never strayed far from the top-scored card. Nicely done."] = ["Nas suas últimas {0} escolhas você nunca se afastou muito da carta com melhor nota. Muito bem.", "Dans vos {0} derniers choix, vous ne vous êtes jamais beaucoup éloigné de la carte la mieux notée. Bien joué.", "Bei deinen letzten {0} Wahlen bist du nie weit von der bestbewerteten Karte abgewichen. Gut gemacht.", "Trong {0} lần chọn gần đây bạn không bao giờ chọn quá xa thẻ điểm cao nhất. Làm tốt lắm.", "최근 {0}번 선택에서 항상 최고점 카드 근처를 선택했습니다. 잘하셨어요."],
        ["Your final build matches the app's in {0} of 6 items on average. If a purchase doesn't convince you, the panel's “Other option ›” gives you the next one; and if you'd rather play another build, lock it in “BUILD TYPE”."] = ["Sua build final coincide com a do app em {0:0.#} de 6 itens em média. Se uma compra não te convence, “Outra opção ›” no painel te dá a seguinte; e se preferir jogar outra build, fixe-a em “TIPO DE BUILD”.", "Votre build finale correspond à celle de l'app sur {0:0.#} objets sur 6 en moyenne. Si un achat ne vous convainc pas, « Autre option › » dans le panneau vous donne le suivant ; et si vous préférez une autre build, fixez-la dans « TYPE DE BUILD ».", "Dein finaler Build stimmt im Schnitt bei {0:0.#} von 6 Items mit dem der App überein. Wenn dich ein Kauf nicht überzeugt, gibt dir „Andere Option ›“ im Panel die nächste; und wenn du lieber einen anderen Build spielst, leg ihn unter „BUILD-TYP“ fest.", "Build cuối của bạn trùng với build của ứng dụng {0:0.#}/6 món trung bình. Nếu một món không thuyết phục bạn, “Lựa chọn khác ›” trong bảng sẽ cho món tiếp theo; còn nếu muốn chơi build khác, hãy khóa trong “KIỂU BUILD”.", "최종 빌드가 평균 6개 중 {0:0.#}개에서 앱과 일치합니다. 구매가 마음에 들지 않으면 패널의 \"다른 옵션 ›\"을, 다른 빌드를 원하면 \"빌드 타입\"에서 고정하세요."],
        ["Very popular"] = ["Muito popular", "Très populaire", "Sehr beliebt", "Rất phổ biến", "매우 인기"],
        ["Popular"] = ["Popular", "Populaire", "Beliebt", "Phổ biến", "인기"],
        ["Unpopular"] = ["Pouco popular", "Peu populaire", "Wenig beliebt", "Ít phổ biến", "비인기"],
        ["Rarely picked"] = ["Raramente escolhido", "Rarement choisi", "Selten gewählt", "Hiếm khi được chọn", "거의 선택되지 않음"],
        ["what almost everyone takes ({0}%); nothing else clearly wins more"] = ["o que quase todos pegam ({0:0}%); nenhum outro ganha claramente mais", "ce que presque tout le monde prend ({0:0} %) ; aucun autre ne gagne nettement plus", "was fast alle nehmen ({0:0} %); nichts anderes gewinnt klar mehr", "lựa chọn gần như ai cũng lấy ({0:0}%); không lựa chọn nào khác thắng rõ rệt hơn", "거의 모두가 선택 ({0:0}%); 다른 것이 뚜렷하게 더 승리하지 않음"],
        ["wins {0} more than {1}, the most used ({2}%)"] = ["ganha {0:+0.0%;-0.0%} a mais que {1}, o mais usado ({2:0}%)", "gagne {0:+0.0%;-0.0%} de plus que {1}, le plus utilisé ({2:0} %)", "gewinnt {0:+0.0%;-0.0%} mehr als {1}, das meistgenutzte ({2:0} %)", "thắng nhiều hơn {0:+0.0%;-0.0%} so với {1}, lựa chọn phổ biến nhất ({2:0}%)", "가장 많이 사용된 {1} ({2:0}%)보다 {0:+0.0%;-0.0%} 더 승리"],
        ["The League client didn't answer"] = ["O cliente do LoL não respondeu", "Le client de LoL n'a pas répondu", "Der LoL-Client hat nicht geantwortet", "Client LoL không phản hồi", "리그 오브 레전드 클라이언트가 응답하지 않음"],
        ["You took {0}"] = ["Você pegou {0}", "Vous avez pris {0}", "Du hast {0} genommen", "Bạn đã lấy {0}", "{0} 선택됨"],
        ["Couldn't take {0} (the bench may still be locked)"] = ["Não foi possível pegar {0} (o banco pode ainda estar bloqueado)", "Impossible de prendre {0} (le banc est peut-être encore verrouillé)", "{0} konnte nicht genommen werden (die Bank ist vielleicht noch gesperrt)", "Không lấy được {0} (hàng chờ có thể vẫn đang khóa)", "{0} 선택 불가 (교환석이 아직 잠겨있을 수 있음)"],
        ["Done: the game will open borderless"] = ["Pronto: o jogo vai abrir sem bordas", "C'est fait : le jeu s'ouvrira en mode sans bordure", "Erledigt: das Spiel öffnet sich randlos", "Xong: trò chơi sẽ mở ở chế độ không viền", "완료: 게임이 테두리 없는 창 모드로 실행됩니다"],
        ["Couldn't change it; use Settings › Video › Window mode"] = ["Não foi possível mudar; use Configurações › Vídeo › Modo de janela", "Impossible de le changer ; utilisez Paramètres › Vidéo › Mode fenêtre", "Konnte nicht geändert werden; nutze Einstellungen › Video › Fenstermodus", "Không đổi được; hãy dùng Cài đặt › Hình ảnh › Chế độ cửa sổ", "변경 불가; 설정 › 영상 › 창 모드 사용"],
        ["Mayhem Advisor · Your feedback"] = ["Mayhem Advisor · Sua opinião", "Mayhem Advisor · Votre avis", "Mayhem Advisor · Deine Meinung", "Mayhem Advisor · Ý kiến của bạn", "Mayhem Advisor · 의견 보내기"],
        ["Play a few more ARAM: Mayhem games and you'll see tips based on your own games here."] = ["Jogue mais algumas partidas de ARAM: Desordem e aqui você verá dicas baseadas nas suas próprias partidas.", "Jouez encore quelques parties d'ARAM du chaos et vous verrez ici des conseils basés sur vos propres parties.", "Spiel noch ein paar Runden ARAM: Chaos, dann siehst du hier Tipps aus deinen eigenen Spielen.", "Chơi thêm vài trận ARAM: Hỗn Loạn và bạn sẽ thấy ở đây các mẹo dựa trên chính các trận của bạn.", "무작위 총력전을 몇 판 더 플레이하면 내 게임 기반 팁이 여기 표시됩니다."],
        ["Looking good: keep using the augment scores and the “Adapt” tab when the enemy team leans hard into one damage type."] = ["Tudo certo: continue usando as notas dos aprimoramentos e a aba “Adaptar” quando o time inimigo for muito de um tipo de dano.", "Tout va bien : continuez à utiliser les notes des optimisations et l'onglet « Adapter » quand l'équipe ennemie mise beaucoup sur un type de dégâts.", "Sieht gut aus: nutze weiter die Bewertungen der Augmentierungen und den Tab „Anpassen“, wenn das gegnerische Team stark auf eine Schadensart setzt.", "Ổn rồi: tiếp tục dùng điểm Nâng Cấp và thẻ “Thích ứng” khi đội địch thiên hẳn về một loại sát thương.", "잘하고 있어요: 증강 점수와 적팀이 한 피해 유형에 집중할 때 \"적응\" 탭을 계속 활용하세요."],
        ["The most used summoner spell pair in Mayhem is {0}: {1} of players take it (mayhemmeta). In champion select, the panel tells you which wins more on your champion."] = ["A dupla de feitiços mais usada na Desordem é {0}: {1:P0} dos jogadores a pegam (mayhemmeta). Na seleção de campeões, o painel diz qual ganha mais com seu campeão.", "La paire de sorts la plus utilisée en ARAM du chaos est {0} : {1:P0} des joueurs la prennent (mayhemmeta). En sélection des champions, le panneau vous dit laquelle gagne le plus avec votre champion.", "Das meistgenutzte Beschwörerzauber-Paar in ARAM: Chaos ist {0}: {1:P0} der Spieler nehmen es (mayhemmeta). In der Championauswahl sagt dir das Panel, welches mit deinem Champion mehr gewinnt.", "Cặp phép bổ trợ được dùng nhiều nhất ở Hỗn Loạn là {0}: {1:P0} người chơi chọn (mayhemmeta). Khi chọn tướng, bảng sẽ cho biết cặp nào thắng nhiều hơn với tướng của bạn.", "무작위 총력전 가장 많이 사용된 소환사 주문 조합은 {0}: {1:P0}가 선택 (mayhemmeta). 챔피언 선택 시 패널이 내 챔피언에 더 좋은 조합을 알려줍니다."],
        ["It's #{0} of {1} champions in Mayhem: it wins {2}% of its games ({3} tier)."] = ["É o #{0} de {1} campeões na Desordem: ganha {2:0.#}% das partidas (tier {3}).", "C'est le #{0} sur {1} champions en ARAM du chaos : il gagne {2:0.#} % de ses parties (tier {3}).", "Er ist #{0} von {1} Champions in ARAM: Chaos: er gewinnt {2:0.#} % seiner Spiele (Tier {3}).", "Đứng hạng {0}/{1} tướng ở Hỗn Loạn: thắng {2:0.#}% số trận (hạng {3}).", "무작위 총력전 {1}명 챔피언 중 {0}위: 승률 {2:0.#}% (티어 {3})."],
        ["Most players go {0}: {1} of games (aramkit)."] = ["A maioria vai de {0}: {1:P0} das partidas (aramkit).", "La plupart jouent {0} : {1:P0} des parties (aramkit).", "Die meisten spielen {0}: {1:P0} der Spiele (aramkit).", "Phần lớn người chơi đi {0}: {1:P0} số trận (aramkit).", "대부분 {0} 선택: 게임의 {1:P0} (aramkit)."],
        ["Most players go {0} ({1}), but the {2} build ({3}) wins more: {4}% vs {5}%. In game you can lock it in “BUILD TYPE”."] = ["A maioria vai de {0} ({1:P0}), mas a build {2} ({3:P0}) ganha mais: {4:0.#}% contra {5:0.#}%. Na partida você pode fixá-la em “TIPO DE BUILD”.", "La plupart jouent {0} ({1:P0}), mais la build {2} ({3:P0}) gagne plus : {4:0.#} % contre {5:0.#} %. En partie, vous pouvez la fixer dans « TYPE DE BUILD ».", "Die meisten spielen {0} ({1:P0}), aber der {2}-Build ({3:P0}) gewinnt mehr: {4:0.#} % gegen {5:0.#} %. Im Spiel kannst du ihn unter „BUILD-TYP“ festlegen.", "Phần lớn đi {0} ({1:P0}), nhưng build {2} ({3:P0}) thắng nhiều hơn: {4:0.#}% so với {5:0.#}%. Trong trận bạn có thể khóa nó ở “KIỂU BUILD”.", "대부분 {0} ({1:P0}) 선택하지만, {2} 빌드 ({3:P0})가 더 승리: {4:0.#}% vs {5:0.#}%. 게임 중 \"빌드 타입\"에서 고정하세요."],
        ["Spells: {0} ({1})."] = ["Feitiços: {0} ({1}).", "Sorts : {0} ({1}).", "Zauber: {0} ({1}).", "Phép bổ trợ: {0} ({1}).", "소환사 주문: {0} ({1})."],
        ["Skills: {0} max {1} (aramkit)."] = ["Habilidades: {0:P0} maximiza {1} (aramkit).", "Compétences : {0:P0} montent {1} en premier (aramkit).", "Fähigkeiten: {0:P0} maximieren {1} (aramkit).", "Kỹ năng: {0:P0} nâng tối đa {1} (aramkit).", "스킬: {0:P0}가 {1} 먼저 최대화 (aramkit)."],
        ["Of what {0} players buy, {1} wins the most: {2}% in ~{3} games ({4}% buy it)."] = ["Do que os jogadores de {0} compram, {1} é o que mais ganha: {2:0.#}% em ~{3:N0} partidas ({4:0}% compram).", "Parmi ce qu'achètent les joueurs de {0}, {1} gagne le plus : {2:0.#} % sur ~{3:N0} parties ({4:0} % l'achètent).", "Von dem, was {0}-Spieler kaufen, gewinnt {1} am meisten: {2:0.#} % in ~{3:N0} Spielen ({4:0} % kaufen es).", "Trong các món người chơi {0} mua, {1} thắng nhiều nhất: {2:0.#}% trong ~{3:N0} trận ({4:0}% mua).", "{0} 플레이어가 구매하는 것 중 {1}이 가장 많이 승리: ~{3:N0}게임에서 {2:0.#}% ({4:0}%가 구매)."],
        ["Scales without limit (stacks that keep growing): the longer the game, the stronger it gets."] = ["Escala sem limite (acúmulos que não param de crescer): quanto mais longa a partida, mais forte fica.", "Évolue sans limite (des cumuls qui grandissent sans cesse) : plus la partie dure, plus il devient fort.", "Skaliert ohne Grenze (Steigerungen, die immer weiter wachsen): je länger das Spiel, desto stärker.", "Mạnh lên không giới hạn (cộng dồn tăng mãi): trận càng dài càng mạnh.", "무한 성장 (계속 쌓이는 스택): 게임이 길수록 더 강해집니다."],
        ["Strong in long games: don't despair if the start is slow."] = ["Forte em partidas longas: não desanime se o começo for lento.", "Fort dans les longues parties : ne désespérez pas si le début est lent.", "Stark in langen Spielen: verzweifle nicht, wenn der Anfang langsam ist.", "Mạnh ở trận dài: đừng nản nếu đầu trận chậm.", "장기전에 강함: 초반이 느려도 포기하지 마세요."],
        ["Most used boots: {0} ({1}%), after the first item."] = ["Botas mais usadas: {0} ({1:0}%), depois do primeiro item.", "Bottes les plus utilisées : {0} ({1:0} %), après le premier objet.", "Meistgenutzte Stiefel: {0} ({1:0} %), nach dem ersten Item.", "Giày được dùng nhiều nhất: {0} ({1:0}%), sau món đầu tiên.", "가장 많이 사용된 신발: {0} ({1:0}%), 첫 아이템 이후."],
        ["Mage"] = ["Mago", "Mage", "Magier", "Pháp sư", "마법사"],
        ["Support"] = ["Suporte", "Support", "Supporter", "Hỗ trợ", "서포터"],
