        ["Augment picked: {0}"] = ["Aprimoramento escolhido: {0}", "Optimisation choisie : {0}", "Augmentierung gewählt: {0}", "Đã chọn Nâng Cấp: {0}", "증강 선택됨: {0}"],
        ["Victory with {0} ({1}/{2}/{3}). Click to see the summary."] = ["Vitória com {0} ({1}/{2}/{3}). Clique para ver o resumo.", "Victoire avec {0} ({1}/{2}/{3}). Cliquez pour voir le résumé.", "Sieg mit {0} ({1}/{2}/{3}). Klicke, um die Zusammenfassung zu sehen.", "Thắng với {0} ({1}/{2}/{3}). Bấm để xem tóm tắt.", "{0}로 승리 ({1}/{2}/{3}). 클릭하여 요약 확인."],
        ["Defeat with {0} ({1}/{2}/{3}). Click to see the summary."] = ["Derrota com {0} ({1}/{2}/{3}). Clique para ver o resumo.", "Défaite avec {0} ({1}/{2}/{3}). Cliquez pour voir le résumé.", "Niederlage mit {0} ({1}/{2}/{3}). Klicke, um die Zusammenfassung zu sehen.", "Thua với {0} ({1}/{2}/{3}). Bấm để xem tóm tắt.", "{0}로 패배 ({1}/{2}/{3}). 클릭하여 요약 확인."],
        ["Install version {0}"] = ["Instalar a versão {0}", "Installer la version {0}", "Version {0} installieren", "Cài phiên bản {0}", "버전 {0} 설치"],
        ["Microsoft Edge WebView2 is missing. Install it from Microsoft's website and open the app again."] = ["Falta o Microsoft Edge WebView2. Instale-o pelo site da Microsoft e abra o app de novo.", "Microsoft Edge WebView2 est manquant. Installez-le depuis le site de Microsoft et rouvrez l'app.", "Microsoft Edge WebView2 fehlt. Installiere es von der Microsoft-Website und öffne die App erneut.", "Thiếu Microsoft Edge WebView2. Hãy cài từ trang web của Microsoft rồi mở lại ứng dụng.", "Microsoft Edge WebView2가 없습니다. Microsoft 웹사이트에서 설치 후 앱을 다시 여세요."],
