        ["Inventory full: no room for more items."] = ["Inventário cheio: não cabem mais itens.", "Inventaire plein : plus de place pour d'autres objets.", "Inventar voll: kein Platz für weitere Items.", "Túi đồ đầy: không còn chỗ cho món khác.", "인벤토리 가득 참: 아이템을 더 추가할 공간 없음."],
        ["Not enough data yet."] = ["Ainda não há dados suficientes.", "Pas encore assez de données.", "Noch nicht genug Daten.", "Chưa đủ dữ liệu.", "아직 데이터가 부족합니다."],
        ["YOUR AUGMENTS"] = ["SEUS APRIMORAMENTOS", "VOS OPTIMISATIONS", "DEINE AUGMENTIERUNGEN", "NÂNG CẤP CỦA BẠN", "내 증강"],
